/** Request to calculate additional fees. */
export interface CalculateAdditionalFeesRequest {
  /**
   * Line items in the cart or checkout. Each line item represents a product with quantity and pricing information.
   * @maxSize 300
   */
  lineItems?: LineItem[];
  /** Address where the order will be shipped. Used to calculate location-based fees or determine applicable regulations. */
  shippingAddress?: Address;
  /** Information about the buyer making the purchase. */
  buyerDetails?: BuyerDetails;
  /**
   * Discounts applied to the cart or checkout. Includes coupons, merchant discounts, and discount rules.
   * @maxSize 320
   */
  appliedDiscounts?: AppliedDiscount[];
  /** Information about the selected shipping method and its associated costs. */
  shippingInfo?: ShippingInformation;
  /**
   * Persistent ID that correlates between the various eCommerce elements: cart, checkout, and order. Use this to tie additional-fee calculations to a specific purchase flow across the cart, checkout, and resulting order.
   * @format GUID
   */
  purchaseFlowId?: string | null;
  /**
   * ID of the business location fulfilling the order. Learn more about the [Locations API](https://dev.wix.com/docs/rest/business-management/locations/introduction).
   * @format GUID
   */
  businessLocationId?: string | null;
  /**
   * Subtotal of all line items before additional fees, shipping, and tax. Calculated as the sum of `lineItems[i].price * lineItems[i].quantity` across all line items. Whether already-applied discounts are reflected in this value depends on `itemDiscountsAppliedToPrices` and the cart's discount-application mode.
   * @decimalValue options { gte:0, lte:1000000000000000, maxScale:3 }
   */
  subtotal?: string | null;
  /**
   * Whether SPECIFIC_ITEMS discounts are applied directly to item prices.
   *
   * When `true`:
   * + SPECIFIC_ITEMS discounts reduce item `price`, which is reflected in the subtotal.
   * + GLOBAL discounts are applied on top of the subtotal, without modifying item `price`.
   *
   * When `false` (current behavior):
   * + All coupons and merchant discounts are treated as GLOBAL; item prices are unchanged.
   *
   * Note: SPECIFIC_ITEMS automatic discounts are already applied to item prices, regardless of this setting.
   *
   * Default: `false`
   * @internal
   */
  itemDiscountsAppliedToPrices?: boolean;
  /**
   * Custom field data for the cart or checkout.
   *
   * [Extended fields](https://dev.wix.com/docs/build-apps/develop-your-app/extensions/backend-extensions/schema-plugins/about-schema-plugin-extensions) must be configured in the app dashboard before they can be accessed with API calls.
   */
  extendedFields?: ExtendedFields;
  /**
   * ID of the site payment method type the customer selected to pay with. Learn more about the [Site Payment Method Types API](https://dev.wix.com/docs/api-reference/business-management/payments/site-payment-method-types/introduction).
   *
   * Available only when the customer selects a payment method during the purchase flow.
   * @internal
   * @format GUID
   */
  sitePaymentMethodTypeId?: string | null;
}

/** Line item in a cart or checkout. */
export interface LineItem {
  /**
   * Line item ID.
   * @minLength 1
   * @maxLength 100
   */
  _id?: string;
  /**
   * Number of this item in the cart or checkout.
   * @max 100000
   */
  quantity?: number | null;
  /** Reference to the product in the catalog. Contains the catalog app ID and product information. */
  catalogReference?: CatalogReference;
  /**
   * Name of the product. Displayed to the site visitor on cart and checkout pages.
   * @maxLength 200
   */
  productName?: string | null;
  /**
   * Price per unit of the product.
   * @decimalValue options { gte:0 }
   */
  price?: string;
  /** Physical properties of the product, such as weight and dimensions. Used for calculating shipping costs and fees that depend on product characteristics. */
  physicalProperties?: PhysicalProperties;
  /**
   * Deposit amount required for this line item. For example, a bottle deposit for beverages.
   * @format DECIMAL_VALUE
   */
  depositAmount?: string | null;
  /**
   * Product options selected for this line item. For example, size, color, or custom engraving. Each modifier group represents a type of option, such as "Size" with values like "Small", "Medium", "Large".
   * @maxSize 25
   */
  modifierGroups?: ModifierGroup[];
}

/** Used for grouping line items. Sent when an item is added to a cart, checkout, or order. */
export interface CatalogReference {
  /**
   * ID of the item within the catalog it belongs to.
   * @minLength 1
   * @maxLength 36
   */
  catalogItemId?: string;
  /**
   * ID of the app providing the catalog.
   *
   * You can get your app's ID from its page in the [app dashboard](https://dev.wix.com/dc3/my-apps/).
   *
   * For items from Wix catalogs, the following values always apply:
   * + Wix Stores: `"215238eb-22a5-4c36-9e7b-e7c08025e04e"`
   * + Wix Bookings: `"13d21c63-b5ec-5912-8397-c3a5ddb27a97"`
   * + Wix Restaurants: `"9a5d83fd-8570-482e-81ab-cfa88942ee60"`
   * @minLength 1
   */
  appId?: string;
  /**
   * Additional item details in `key:value` pairs.
   *
   * Use this optional field for more specificity with item selection. The values of the `options` field differ depending on which catalog is providing the items.
   *
   * For Wix Stores products, learn more about integrating with [Catalog V3](https://dev.wix.com/docs/api-reference/business-solutions/stores/catalog-v3/e-commerce-integration)
   * or [Catalog V1](https://dev.wix.com/docs/api-reference/business-solutions/stores/catalog-v1/catalog/e-commerce-integration), depending on [the version the site uses](https://dev.wix.com/docs/api-reference/business-solutions/stores/catalog-versioning/introduction).
   */
  options?: Record<string, any> | null;
}

export interface PhysicalProperties {
  /** Line item weight. Measurement unit matches the weight unit specified in `weightUnit` in the request. */
  weight?: number | null;
  /**
   * Stock-keeping unit. Learn more about [SKUs](https://www.wix.com/encyclopedia/definition/stock-keeping-unit-sku).
   * @maxLength 40
   */
  sku?: string | null;
  /** Whether this line item is shippable. */
  shippable?: boolean;
  /**
   * Product dimensions (length, width, height of the physical product).
   * @internal
   */
  productDimensions?: Dimensions;
  /**
   * Package dimensions (length, width, height of the shipping package).
   * @internal
   */
  packageDimensions?: Dimensions;
}

export interface Dimensions {
  /**
   * Length. Measurement unit is handled at the system level (metric/imperial).
   * @decimalValue options { gte:0, lte:999999999, maxScale:6 }
   */
  length?: string | null;
  /**
   * Width. Measurement unit is handled at the system level (metric/imperial).
   * @decimalValue options { gte:0, lte:999999999, maxScale:6 }
   */
  width?: string | null;
  /**
   * Height. Measurement unit is handled at the system level (metric/imperial).
   * @decimalValue options { gte:0, lte:999999999, maxScale:6 }
   */
  height?: string | null;
  /** Unit of measurement for dimensions (length, width, height). */
  unit?: DimensionsUnit;
}

export enum DimensionsUnit {
  UNKNOWN_DIMENSIONS_UNIT = 'UNKNOWN_DIMENSIONS_UNIT',
  /** Millimeters. */
  MM = 'MM',
  /** Centimeters. */
  CM = 'CM',
  /** Meters. */
  M = 'M',
  /** Inches. */
  IN = 'IN',
  /** Feet. */
  FT = 'FT',
  /** Yards. */
  YD = 'YD',
}

export interface ModifierGroup {
  /**
   * Modifier group ID.
   * @minLength 1
   * @maxLength 36
   */
  _id?: string;
  /** Modifier group name. */
  name?: TranslatableString;
  /**
   * List of modifiers in this group.
   * @minSize 1
   * @maxSize 25
   */
  modifiers?: ItemModifier[];
}

export interface TranslatableString {
  /**
   * __Required.__ String in the site's default language as defined in the [request envelope](https://dev.wix.com/docs/build-apps/develop-your-app/frameworks/self-hosting/supported-extensions/backend-extensions/add-self-hosted-service-plugin-extensions#request-envelope).
   *
   * Min: 1 character.
   * Max: 200 characters.
   * @minLength 1
   * @maxLength 200
   */
  original?: string;
  /**
   * String translated into the buyer's language.
   *
   * Min: 1 character.
   * Max: 400 characters.
   * Default: Same as `original`.
   * @minLength 1
   * @maxLength 400
   */
  translated?: string | null;
}

export interface ItemModifier {
  /**
   * Modifier ID.
   * @minLength 1
   * @maxLength 36
   */
  _id?: string;
  /**
   * The quantity of this modifier.
   * @min 1
   * @max 100000
   */
  quantity?: number | null;
  /** Primary display label for the modifier. */
  label?: TranslatableString;
  /** Additional details. */
  details?: TranslatableString;
  /**
   * The price of the modifier.
   * @decimalValue options { gte:0, lte:1000000000000000, maxScale:3 }
   */
  price?: string | null;
}

/** Physical address */
export interface Address {
  /**
   * Two-letter country code in [ISO-3166 alpha-2](https://www.iso.org/obp/ui/#search/code/) format.
   * @format COUNTRY
   */
  country?: string | null;
  /**
   * Code for a subdivision (such as state, prefecture, or province) in [ISO 3166-2](https://www.iso.org/standard/72483.html) format.
   * @maxLength 50
   */
  subdivision?: string | null;
  /**
   * City name.
   * @maxLength 50
   */
  city?: string | null;
  /**
   * Postal or zip code.
   * @maxLength 50
   */
  postalCode?: string | null;
  /** Street address. */
  streetAddress?: StreetAddress;
  /**
   * Main address line (usually street name and number).
   * @maxLength 150
   */
  addressLine1?: string | null;
  /**
   * Free text providing more detailed address info. Usually contains apt, suite, floor.
   * @maxLength 100
   */
  addressLine2?: string | null;
  /** Geocode object containing latitude and longitude coordinates. */
  location?: AddressLocation;
  /**
   * Country's full name.
   * @readonly
   */
  countryFullname?: string | null;
  /**
   * Subdivision full-name.
   * @readonly
   */
  subdivisionFullname?: string | null;
}

export interface StreetAddress {
  /** Street number. */
  number?: string;
  /** Street name. */
  name?: string;
  /**
   * Apartment number.
   * @internal
   */
  apt?: string;
  /**
   * Optional address line 1
   * @internal
   */
  formattedAddressLine?: string | null;
}

export interface AddressLocation {
  /** Address latitude. */
  latitude?: number | null;
  /** Address longitude. */
  longitude?: number | null;
}

/** Information about the buyer making the purchase. */
export interface BuyerDetails {
  /** Contact information for the buyer, including name, email, phone number, and address. */
  contactDetails?: FullAddressContactDetails;
}

/** Full contact details for an address */
export interface FullAddressContactDetails {
  /** Contact's first name. */
  firstName?: string | null;
  /** Contact's last name. */
  lastName?: string | null;
  /**
   * Contact's full name.
   * @internal
   */
  fullName?: string | null;
  /**
   * Contact's phone number.
   * @format PHONE
   */
  phone?: string | null;
  /** Contact's company name. */
  company?: string | null;
  /**
   * Email associated with the address.
   * @format EMAIL
   */
  email?: string | null;
  /** Tax info. Currently usable only in Brazil. */
  vatId?: VatId;
}

export interface VatId {
  /** Customer's tax ID. */
  _id?: string;
  /**
   * Tax type.
   *
   * Supported values:
   * + `CPF`: for individual tax payers
   * + `CNPJ`: for corporations
   */
  type?: VatType;
}

/** tax info types */
export enum VatType {
  UNSPECIFIED = 'UNSPECIFIED',
  /** CPF - for individual tax payers. */
  CPF = 'CPF',
  /** CNPJ - for corporations */
  CNPJ = 'CNPJ',
}

/** Discount applied to the cart or checkout. */
export interface AppliedDiscount extends AppliedDiscountDiscountSourceOneOf {
  /** Coupon code applied by the site visitor. */
  coupon?: Coupon;
  /** Manual discount applied by the merchant during checkout or order processing. */
  merchantDiscount?: MerchantDiscount;
  /** Automatic discount rule configured by the merchant. */
  discountRule?: DiscountRule;
  /** Type of this discount. */
  discountType?: DiscountType;
  /**
   * IDs of line items this discount applies to.
   *
   * Available only when `discountType` is `SPECIFIC_ITEMS`.
   * @format GUID
   */
  lineItemIds?: string[];
}

/** @oneof */
export interface AppliedDiscountDiscountSourceOneOf {
  /** Coupon code applied by the site visitor. */
  coupon?: Coupon;
  /** Manual discount applied by the merchant during checkout or order processing. */
  merchantDiscount?: MerchantDiscount;
  /** Automatic discount rule configured by the merchant. */
  discountRule?: DiscountRule;
}

/** Type of discount indicating what the discount applies to. */
export enum DiscountType {
  /** Discount applies to the entire order. */
  GLOBAL = 'GLOBAL',
  /** Discount applies only to specific items in the cart. */
  SPECIFIC_ITEMS = 'SPECIFIC_ITEMS',
  /** Discount applies to shipping costs. */
  SHIPPING = 'SHIPPING',
}

/** Coupon applied to the cart or checkout. */
export interface Coupon {
  /** Coupon ID. */
  _id?: string;
  /** Coupon code entered by the site visitor. For example, "SUMMER20" or "WELCOME10". */
  code?: string;
  /** Display name of the coupon. Shown to the site visitor on the cart and checkout pages. */
  name?: string;
  /**
   * Discount amount provided by the coupon. Can represent a fixed amount or a calculated percentage discount value.
   * @decimalValue options { gte:0, lte:1000000000000000 }
   */
  amount?: string;
}

/** Manual discount applied by the merchant. */
export interface MerchantDiscount {
  /**
   * Discount amount applied by the merchant.
   * @decimalValue options { gte:0, lte:1000000000000000 }
   */
  amount?: string;
}

/** Automatic discount rule applied to the cart or checkout. */
export interface DiscountRule {
  /**
   * Discount rule ID.
   * @format GUID
   */
  _id?: string;
  /** Name of the discount rule in original and translated forms. */
  name?: DiscountRuleName;
  /**
   * Discount amount applied by the rule. Can represent a fixed amount or a calculated percentage discount value.
   * @decimalValue options { gte:0, lte:1000000000000000 }
   */
  amount?: string;
}

/** Display names for a discount rule. */
export interface DiscountRuleName {
  /**
   * Original name of the discount rule as configured by the merchant.
   * @minLength 1
   * @maxLength 256
   */
  original?: string;
  /**
   * Translated name of the discount rule. When provided, this value is displayed to the site visitor instead of `original`.
   * @minLength 1
   * @maxLength 500
   */
  translated?: string | null;
}

/** Information about shipping for the order. */
export interface ShippingInformation {
  /** Shipping method and carrier selected by the site visitor. */
  selectedCarrierServiceOption?: SelectedCarrierServiceOption;
}

/** Shipping method and carrier service selected by the site visitor. */
export interface SelectedCarrierServiceOption {
  /**
   * Unique code identifying the carrier service. For example, "usps-priority" or "fedex-ground".
   * @maxLength 100
   */
  code?: string;
  /**
   * Display name of the shipping method shown to the site visitor. For example, "USPS Priority Mail" or "FedEx Ground".
   * @maxLength 250
   * @readonly
   */
  title?: string;
  /**
   * Delivery details including estimated delivery time and pickup information.
   * @readonly
   */
  logistics?: DeliveryLogistics;
  /**
   * Cost of the shipping method.
   * @readonly
   */
  cost?: SelectedCarrierServiceOptionPrices;
  /**
   * Additional charges associated with the shipping method, such as handling fees or insurance.
   * @maxSize 100
   */
  otherCharges?: SelectedCarrierServiceOptionOtherCharge[];
}

/** Delivery and logistics information for the order. */
export interface DeliveryLogistics {
  /**
   * Estimated delivery time shown to the site visitor. For example, "3-5 business days" or "Ships by Friday, March 15".
   * @maxLength 500
   */
  deliveryTime?: string | null;
  /**
   * Special instructions for delivery or pickup. For example, "Leave at front door" or "Call upon arrival".
   * @maxLength 1000
   */
  instructions?: string | null;
  /**
   * Details for pickup orders where the customer collects the order instead of having it delivered.
   *
   * Available only when the order uses a pickup shipping method.
   */
  pickupDetails?: PickupDetails;
}

/** Details for pickup orders where the customer collects the order instead of having it delivered. */
export interface PickupDetails {
  /** Address where the customer will pick up the order. */
  address?: Address;
  /**
   * Whether the pickup address is a business location. Affected tax calculation.
   *
   * Deprecated. Use `pickupMethod` to distinguish between store pickup and pickup-point.
   * @deprecated
   */
  businessLocation?: boolean;
  /** Method the customer will use to pick up the order. */
  pickupMethod?: PickupMethod;
}

/** Method used for pickup. */
export enum PickupMethod {
  /** Customer picks up the order at a store or business location. */
  STORE_PICKUP = 'STORE_PICKUP',
  /** Customer picks up the order at a designated pickup point, such as a locker or collection center. */
  PICKUP_POINT = 'PICKUP_POINT',
}

/** Pricing information for a shipping method. */
export interface SelectedCarrierServiceOptionPrices {
  /**
   * Base price of the shipping method before discounts.
   * @decimalValue options { gte:0, lte:1000000000000000 }
   */
  price?: string;
  /**
   * Total discount amount applied to the shipping cost.
   * @decimalValue options { gte:0, lte:1000000000000000 }
   */
  totalDiscount?: string | null;
}

/** Additional charge associated with a shipping method. */
export interface SelectedCarrierServiceOptionOtherCharge {
  /** Type of charge. */
  type?: ChargeType;
  /**
   * Additional details about the charge. For example, "Signature required" for insurance.
   * @maxLength 200
   */
  details?: string | null;
  /** Cost of the additional charge. */
  cost?: SelectedCarrierServiceOptionPrices;
}

/** Type of additional shipping charge. */
export enum ChargeType {
  /** Handling fee charged for processing the shipment. */
  HANDLING_FEE = 'HANDLING_FEE',
  /** Insurance fee to protect the shipment during transit. */
  INSURANCE = 'INSURANCE',
}

export interface ExtendedFields {
  /**
   * Extended field data. Each key corresponds to the namespace of the app that created the extended fields.
   * The value of each key is structured according to the schema defined when the extended fields were configured.
   *
   * You can only access fields for which you have the appropriate permissions.
   *
   * Learn more about [extended fields](https://dev.wix.com/docs/rest/articles/getting-started/extended-fields).
   */
  namespaces?: Record<string, Record<string, any>>;
}

/** Response containing calculated additional fees. */
export interface CalculateAdditionalFeesResponse {
  /**
   * Additional fees calculated for the cart or checkout. Each fee represents a separate line item that will be added to the order total.
   * @maxSize 100
   */
  additionalFees?: AdditionalFee[];
  /**
   * Three-letter currency code in [ISO-4217 alphabetic](https://en.wikipedia.org/wiki/ISO_4217) format. Must match the currency of the Wix site where the fees are being calculated — if it doesn't match, the fees in this response are silently filtered out and not applied to the order.
   * @maxLength 3
   */
  currency?: string;
}

/** Additional fee to be added to an order. */
export interface AdditionalFee {
  /**
   * Unique code identifying the type of fee. For example, `fragile-packaging` or `gift-wrap`. Used for internal tracking and reporting.
   * @minLength 1
   * @maxLength 100
   */
  code?: string | null;
  /**
   * Display name of the fee shown to the site visitor on the cart and checkout pages. For example, "Fragile Packaging Fee" or "Gift Wrapping".
   * @minLength 1
   * @maxLength 50
   */
  name?: string;
  /**
   * Price of the fee, excluding any tax. This amount is added to the order total.
   *
   * If `taxDetails.taxable` is `true`, Wix calculates tax on top of this price — do not include tax in this value.
   * @decimalValue options { gte:0, lte:1000000000000000 }
   */
  price?: string;
  /** Tax information for the fee. Determines whether the fee is taxable and which tax rules apply. */
  taxDetails?: TaxDetails;
  /**
   * IDs of line items this fee applies to. Use this to associate the fee with specific items in the cart. For example, a fragile packaging fee might only apply to breakable items.
   *
   * If empty, the fee applies to the entire order.
   * @format GUID
   */
  lineItemIds?: string[];
  /**
   * Number of subscription billing cycles this fee should be charged for. For example, `3` to charge the fee for the first 3 subscription cycles only.
   *
   * Applies only to orders containing subscription items.
   * @internal
   * @min 1
   * @max 999
   */
  subscriptionCycles?: number | null;
  /**
   * Translated display name of the fee. When provided, this value is shown to the site visitor instead of `name`.
   *
   * Use this field to provide localized fee names based on the site visitor's language preferences.
   * @minLength 1
   * @maxLength 50
   */
  translatedName?: string | null;
}

/** Tax configuration for an additional fee. */
export interface TaxDetails {
  /**
   * Whether the fee is subject to tax. When `true`, Wix applies the site's tax rules to calculate tax on the fee amount.
   *
   * Default: `false`
   */
  taxable?: boolean;
  /**
   * ID of the tax group that defines tax rates and rules for this fee. If provided, Wix uses the specified tax group's configuration instead of the default tax settings.
   *
   * Available only when `taxable` is `true`.
   * @format GUID
   */
  taxGroupId?: string | null;
  /**
   * Address type to calculate tax against for this fee.
   *
   * Available only when `taxable` is `true`.
   */
  taxableAddress?: TaxableAddress;
}

export interface TaxableAddress extends TaxableAddressTaxableAddressDataOneOf {
  /** taxable address type. if this field is selected, the address is automatically resolved, and the tax is calculated accordingly. */
  addressType?: TaxableAddressType;
}

/** @oneof */
export interface TaxableAddressTaxableAddressDataOneOf {
  /** taxable address type. if this field is selected, the address is automatically resolved, and the tax is calculated accordingly. */
  addressType?: TaxableAddressType;
}

export enum TaxableAddressType {
  BUSINESS = 'BUSINESS',
  BILLING = 'BILLING',
  SHIPPING = 'SHIPPING',
}

/** Configuration for the Additional Fees service plugin. */
export interface AdditionalFeesSPIConfig {
  /** Base URI where the service plugin endpoints are hosted. Wix appends the endpoint path to this URI when calling your implementation. For example, if your Calculate Additional Fees endpoint is at `https://my-fees-service.com/v1/calculate-additional-fees`, set this field to `https://my-fees-service.com/`. */
  deploymentUri?: string;
  /**
   * Filter to apply to requests before forwarding them to your implementation. When provided, only requests matching the filter are sent to your service. Use [WQL syntax](https://dev.wix.com/docs/rest/articles/get-started/api-query-language#filters) to define filter conditions.
   * @internal
   */
  filter?: Record<string, any> | null;
}

/**
 * this message is not directly used by any service,
 * it exists to describe the expected parameters that SHOULD be provided to invoked Velo methods as part of open-platform.
 * e.g. SPIs, event-handlers, etc..
 * NOTE: this context object MUST be provided as the last argument in each Velo method signature.
 *
 * Example:
 * ```typescript
 * export function wixStores_onOrderCanceled({ event, metadata }: OrderCanceledEvent) {
 * ...
 * }
 * ```
 */
export interface Context {
  /** A unique identifier of the request. You may print this ID to your logs to help with future debugging and easier correlation with Wix's logs. */
  requestId?: string | null;
  /**
   * [ISO 4217](https://en.wikipedia.org/wiki/ISO_4217) 3-letter currency code.
   * @format CURRENCY
   */
  currency?: string | null;
  /** An object that describes the identity that triggered this request. */
  identity?: IdentificationData;
  /** A string representing a language and region in the format of `"xx-XX"`. First 2 letters represent the language code according to ISO 639-1. This is followed by a dash "-", and then a by 2 capital letters representing the region according to ISO 3166-2. For example, `"en-US"`. */
  languages?: string[];
  /**
   * The service provider app's instance ID.
   * @format GUID
   */
  instanceId?: string | null;
  /**
   * Extension ID in Dev Center.
   * @internal
   * @maxLength 256
   */
  appExtensionId?: string | null;
  /**
   * Extension type in Dev Center.
   * @internal
   * @maxLength 256
   */
  appExtensionType?: string | null;
  /**
   * Invoked function.
   * @internal
   * @maxLength 256
   */
  functionName?: string | null;
}

export enum IdentityType {
  UNKNOWN = 'UNKNOWN',
  ANONYMOUS_VISITOR = 'ANONYMOUS_VISITOR',
  MEMBER = 'MEMBER',
  WIX_USER = 'WIX_USER',
  APP = 'APP',
}

export interface IdentificationData extends IdentificationDataIdOneOf {
  /**
   * ID of a site visitor that has not logged in to the site.
   * @format GUID
   */
  anonymousVisitorId?: string;
  /**
   * ID of a site visitor that has logged in to the site.
   * @format GUID
   */
  memberId?: string;
  /**
   * ID of a Wix user (site owner, contributor, etc.).
   * @format GUID
   */
  wixUserId?: string;
  /**
   * ID of an app.
   * @format GUID
   */
  appId?: string;
  /** @readonly */
  identityType?: IdentityType;
}

/** @oneof */
export interface IdentificationDataIdOneOf {
  /**
   * ID of a site visitor that has not logged in to the site.
   * @format GUID
   */
  anonymousVisitorId?: string;
  /**
   * ID of a site visitor that has logged in to the site.
   * @format GUID
   */
  memberId?: string;
  /**
   * ID of a Wix user (site owner, contributor, etc.).
   * @format GUID
   */
  wixUserId?: string;
  /**
   * ID of an app.
   * @format GUID
   */
  appId?: string;
}
